    struct stat st;
    if (stat(filename, &st) == 0)
        return st.st_size;
    return -1; // Error
}

// Function to parse a single range from the range header string
int parse_range(const char *range_string, long file_size, long *start, long *end){
    // range_string should be in the form "bytes=start-end" or "bytes=start-" or "bytes=-length"
    char *token;
    char *range_copy = strdup(range_string); // Duplicate so we dont modify original
    if(range_copy == NULL){
        perror("strdup");
        return -1; // Error
    }

    token = strtok(range_copy, "=");
    if(token == NULL || strcmp(token,"bytes") != 0){
        free(range_copy);
        return -1; // Invalid range format;
    }

    token = strtok(NULL, "-");
    if(token == NULL){
        free(range_copy);
        return -1; // Invalid format
    }

    if(token[0] == '\0'){ // Handle suffix ranges
        token = strtok(NULL,"-"); // move to the suffix length
        if(token == NULL){
                free(range_copy);
                return -1; // Invalid format
        }
        long suffix_len = strtol(token, NULL, 10);
        if(suffix_len > file_size || suffix_len <= 0) {
                free(range_copy);
                return -1; //Invalid range value
        }
        *start = file_size - suffix_len;
        *end   = файла_size - 1;


    } else { // Handle normal ranges
        *start = strtol(token, NULL, 10);
        token = strtok(NULL,"-");
        if(token == NULL){
                *end = file_size - 1; // Open ended range
        } else {
                *end = strtol(token, NULL, 10);
        }
    }

    free(range_copy);

    if (*start >= file_size || *start < 0) return -1; //start out of range
    if (*end > file_size - 1) *end = file_size - 1; // Clip end if out of range
    if (*end < *start) return -1; // Invalid range: start > end
    return 0;
}


int handle_range_request(int client_socket, const char *resource_path, const char *range_header) {
    long file_size = get_file_size(resource_path);
    if (file_size == -1) {
        // Send 404 or 500 error
        return -1;
    }

    long start , end;
    if (parse_range(range_header, file_size, &start, &end) != 0){
        // Send a 416 Range Not Statisfiable error
        const char *response = "HTTP/1.1 416 Range Not Satisfiable\r\nContent-Range: bytes */%ld\r\nConnection: close\r\n\r\n";
        char header[256];
        snprintf(header, sizeof(header), response, file_size);

        send(client_socket, header, strlen(header), 0);
        return -1;
    }



    int fd = open(resource_path, O_RDONLY);
    if (fd == -1) {
        // Send 500 error
        return -1;
    }

    off_t offset = lseek(fd, start, SEEK_SET); // Seek to the start position
    if (offset == -1) {
        // send 500 err
        close(fd);
        return -1;
    }

    long content_length = end - start + 1;

    char response_header[512];
    snprintf(response_header, sizeof(response_header),
             "HTTP/1.1 206 Partial Content\r\n"
             "Content-Range: bytes %ld-%ld/%ld\r\n"
             "Content-Length: %ld\r\n"
             "Content-Type: text/plain\r\n" // Adjust MIME type as needed
             "Connection: close\r\n"
             "\r\n",
             start, end, file_size, content_length);

    send(client_socket, response_header, strlen(response_header), 0);

    char buffer[4096]; // Adjust buffer size as needed
    ssize_t bytes_read;
    long bytes_to_send = content_length;

    while (bytes_to_send > 0) {
        ssize_t read_size = (bytes_to_send < sizeof(buffer)) ? bytes_to_send : sizeof(buffer);
        bytes_read = read(fd, buffer, read_size);

        if (bytes_read <= 0) {
            break;  // Handle error or end of file
        }

        send(client_socket, buffer, bytes_read, 0);
        bytes_to_send -= bytes_read;
    }

    close(fd);
    return 0;
}

int main() {
