    int client_socket = 5;  // Replace with actual client socket file descriptor
    const char *resource_path = "/tmp/test.txt";  // Example file path
    const char *range_header = "bytes=10-20";    // Example range header

    //Call the main handler
    int result = handle_range_request(client_socket, resource_path, range_header);
    if(result != 0) {
       printf("Error while serving\n");
    }

    close(client_socket); //Cleanup connection from client

    return 0;
}
